package org.sleepwell.app;
import java.time.*;import java.util.*;
/** Original descriptive formula from saved inputs, not a health or sleep-stage score. */
final class RecordedNightScore {
 static final class Dimension {final String title,inputs,formula,missing;final Double value;Dimension(String title,Double value,String inputs,String formula,String missing){this.title=title;this.value=value;this.inputs=inputs;this.formula=formula;this.missing=missing;}}
 final RecordEntry record;final List<Dimension> dimensions;final Double total;final int available;final String unavailable;
 RecordedNightScore(RecordEntry record,List<RecordEntry> records,List<GoalCommitment> goals,long now){this.record=record;List<Dimension> out=new ArrayList<>();boolean actual=record.source.equals("tracked")&&record.healthConnect.isEmpty()&&Set.of(SensorProvenance.MOTION,SensorProvenance.SONAR).contains(record.sensor);boolean bounds=record.edit.start>0&&record.edit.end>record.edit.start&&record.edit.end<=now&&record.edit.end-record.edit.start<=36*3600000L;boolean complete=actual&&bounds&&record.clockChanged==0&&record.interrupted==0&&record.active!=null&&record.active>=0&&record.active<=record.rawEnd-record.rawStart&&record.edit.start>=record.rawStart&&record.edit.end<=record.rawEnd;
  unavailable=!actual?"A known phone/sonar recording is required. Manual, provider and unknown legacy records have no measured recording score.":!bounds?"This record has incomplete or invalid time bounds.":"";
  out.add(goal(record,records,goals,now,actual&&bounds));
  long span=record.edit.end-record.edit.start,kept=bounds?record.duration():0;
  out.add(new Dimension("Recorded continuity",complete?clamp(100d*kept/span):null,complete?duration(kept)+" retained of "+duration(span)+" selected; "+duration(span-kept)+" excluded":"", "100 × reviewed recorded duration ÷ full selected period. Pauses, marked awake periods and accepted awake estimates are excluded from retained duration.",complete?"":!actual?"No known local recording measurements.":record.clockChanged!=0?"The phone clock changed during this recording.":record.interrupted!=0?"Interrupted recording: continuity may be incomplete.":"Known active duration and valid bounds are required."));
  out.add(new Dimension("Your rested rating",actual&&bounds&&record.edit.rated?clamp(100d*record.edit.rating/5):null,record.edit.rated?record.edit.rating+" / 5, explicitly rated by you":"","100 × saved rating ÷ 5. This is subjective, not a sensor measurement.",record.edit.rated?"No eligible phone/sonar recording.":"You have not rated this period. Not rated is different from a saved zero."));
  out.add(timing(record,records,complete));dimensions=List.copyOf(out);double sum=0;int count=0;for(Dimension d:out)if(d.value!=null){sum+=d.value;count++;}available=count;total=unavailable.isEmpty()&&count>=2?sum/count:null;
 }
 private static double clamp(double x){return Math.max(0,Math.min(100,x));}
 static String number(double value){return String.format(Locale.getDefault(),"%.1f",value);}
 static String duration(long ms){long seconds=Math.max(0,ms)/1000;return seconds>=3600?seconds/3600+" h "+seconds/60%60+" min":seconds/60+" min "+seconds%60+" sec";}
 private static Dimension goal(RecordEntry record,List<RecordEntry> records,List<GoalCommitment> goals,long now,boolean eligible){String formula="100 × max(0, 1 − |reviewed goal-day duration − target| ÷ target). Uses the original dated goal, zone and day boundary; overlapping coverage counts once, including other recorded or user-reported periods on that goal date.";String missing="No duration commitment applies to this recorded date.";GoalCommitment selected=null;if(!eligible)missing="No eligible phone/sonar recording.";else if(goals==null)missing="Saved goal history could not be read.";else for(GoalCommitment g:goals){if(!g.metric.equals("duration"))continue;LocalDate day=SleepDay.label(record.edit.end,ZoneId.of(g.zone),g.cutoff);if(day.isBefore(g.start)||day.isAfter(g.through()))continue;if(selected!=null)return new Dimension("Dated-goal duration",null,"",formula,"Multiple saved duration goals apply; resolve goal history first.");selected=g;}
  if(!eligible||selected==null)return new Dimension("Dated-goal duration",null,"",formula,missing);GoalCommitment g=selected;ZoneId zone=ZoneId.of(g.zone);LocalDate date=SleepDay.label(record.edit.end,zone,g.cutoff);if(!date.isBefore(SleepDay.label(now,zone,g.cutoff)))return new Dimension("Dated-goal duration",null,"",formula,"This goal day is still open. Its duration is not final.");if(record.clockChanged!=0||record.interrupted!=0)return new Dimension("Dated-goal duration",null,"",formula,"This selected recording has interrupted or changed-clock timing.");
  List<RecordEntry> projected=new ArrayList<>();int reported=0,provider=0;for(RecordEntry r:records)if(r.edit.end<=now){if(SleepDay.label(r.edit.end,zone,g.cutoff).equals(date)){if(r.clockChanged!=0||r.interrupted!=0||!r.manual()&&r.active==null)return new Dimension("Dated-goal duration",null,"",formula,"A period on this goal date has incomplete or changed-clock timing.");if(r.manual())reported++;if(!r.healthConnect.isEmpty())provider++;}RecordEntry p=new RecordEntry(r.id,r.rawStart,r.rawEnd,r.active,r.source,r.origin,g.zone,r.interrupted,r.clockChanged,r.edit,r.edited,r.updated,r.pauses,r.sensor,r.sensorConfig,r.soundAnalysis,r.healthConnect).awake(r.awake);projected.add(p);}RecordTrends.Day day=RecordTrends.days(projected,new RecordTrends.Range(date,date),g.cutoff).get(date);if(day==null)return new Dimension("Dated-goal duration",null,"",formula,"No reviewed recorded coverage on the goal date.");long duration=day.duration(),target=g.target*60000L;return new Dimension("Dated-goal duration",clamp(100d*(1-Math.abs(duration-target)/(double)target)),date+" · "+duration(duration)+" recorded / "+duration(target)+" target; "+reported+" manual, "+provider+" provider periods included; original "+g.zone+" day boundary "+String.format(Locale.ROOT,"%02d:%02d",g.cutoff/60,g.cutoff%60),formula,"");
 }
 private static boolean main(RecordEntry r){if(!r.source.equals("tracked")||!r.healthConnect.isEmpty()||r.clockChanged!=0||r.interrupted!=0||r.active==null||r.zone.isEmpty()||!Set.of(SensorProvenance.MOTION,SensorProvenance.SONAR).contains(r.sensor)||r.edit.end<=r.edit.start||r.duration()<3*3600000L||r.edit.tags.stream().anyMatch(t->t.equalsIgnoreCase("nap")))return false;try{ZoneId.of(r.zone);return true;}catch(DateTimeException invalid){return false;}}
 private static Dimension timing(RecordEntry record,List<RecordEntry> records,boolean complete){String title="Recorded start consistency",formula="100 × max(0, 1 − circular distance from recent median start ÷ 180 minutes). The 180-minute scale is an original descriptive choice, not a healthy bedtime threshold. Uses 3–7 previous main recordings in 30 days, same saved zone; a fixed noon day boundary groups main periods.";if(!complete||!main(record))return new Dimension(title,null,"",formula,"Needs a complete, known-zone main phone/sonar period of at least 3 hours, without a Nap tag.");ZoneId zone=ZoneId.of(record.zone);LocalDate date=SleepDay.label(record.edit.end,zone,720);Map<LocalDate,RecordEntry> mains=new TreeMap<>();for(RecordEntry r:records){if(!r.zone.equals(record.zone)||!main(r)||r.edit.end>record.edit.end)continue;LocalDate day=SleepDay.label(r.edit.end,zone,720);if(day.isBefore(date.minusDays(30))||day.isAfter(date))continue;RecordEntry old=mains.get(day);if(old==null||r.duration()>old.duration()||r.duration()==old.duration()&&r.id<old.id)mains.put(day,r);}if(mains.get(date)==null||mains.get(date).id!=record.id)return new Dimension(title,null,"",formula,"This period is not the longest eligible main recording on its recorded date.");double current=minute(record,zone);List<Double> starts=new ArrayList<>();List<LocalDate> dates=new ArrayList<>(mains.keySet());dates.sort(Comparator.reverseOrder());for(LocalDate day:dates){if(!day.isBefore(date)||starts.size()==7)continue;double previous=minute(mains.get(day),zone);starts.add(previous);}if(starts.size()<3)return new Dimension(title,null,starts.size()+" previous comparable main recordings",formula,"At least 3 previous complete same-zone main recordings within 30 days are required.");int n=starts.size();double median=0,best=Double.POSITIVE_INFINITY;for(double candidate:starts){double cost=0;for(double start:starts)cost+=Math.abs(wrap(start-candidate));if(cost<best||cost==best&&candidate<median){best=cost;median=candidate;}}double distance=Math.abs(wrap(current-median));return new Dimension(title,clamp(100*(1-distance/180)),number(distance)+" min from circular recent median ("+String.format(Locale.ROOT,"%02d:%02d",((int)median)/60,((int)median)%60)+"); "+n+" previous main recordings; saved zone "+record.zone,formula,"");}
 private static double minute(RecordEntry r,ZoneId zone){LocalTime t=Instant.ofEpochMilli(r.edit.start).atZone(zone).toLocalTime();return t.getHour()*60+t.getMinute()+t.getSecond()/60d;}
 private static double wrap(double minutes){return minutes-1440*Math.floor((minutes+720)/1440);}
}
